                            { id: '501', name: '杭州市' },
                            { id: '502', name: '宁波市' },
                            { id: '503', name: '温州市' },
                            { id: '504', name: '嘉兴市' },
                            { id: '505', name: '绍兴市' }
                        ],
                        '6': [ // 四川
                            { id: '601', name: '成都市' },
                            { id: '602', name: '绵阳市' },
                            { id: '603', name: '德阳市' },
                            { id: '604', name: '宜宾市' },
                            { id: '605', name: '泸州市' }
                        ],
                        '7': [ // 湖北
                            { id: '701', name: '武汉市' },
                            { id: '702', name: '宜昌市' },
                            { id: '703', name: '襄阳市' },
                            { id: '704', name: '荆州市' },
                            { id: '705', name: '黄石市' }
                        ]
                    };

                    // 填充城市下拉框
                    const cities = citiesData[provinceId] || [];
                    cities.forEach(city => {
                        const option = document.createElement('option');
                        option.value = city.id;
                        option.textContent = city.name;
                        citySelect.appendChild(option);
                    });

                    citySelect.disabled = false;
                    hideLoading();
                }, 1000);
            }

            function showLoading() {
                loadingDiv.style.display = 'block';
            }

            function hideLoading() {
                loadingDiv.style.display = 'none';
            }
        });
    </script>
</body>
</html>
